");
return Object.keys(result).length === 1 && result["server.port"] === "8080";

const defaults = { "server.port": "8080", "name": "default" };
const profile = { "server.port": "8081" };
const environment = { "name": "production" };
return resolveProperty("server.port", [defaults, profile, environment]) === "8081" && resolveProperty("name", [defaults, profile, environment]) === "production" && resolveProperty("missing", [defaults, profile, environment]) === undefined;
